const root = join(dirname(fileURLToPath(import.meta.url)), '..');

/** 涓� src/shared/constants.ts 閫愬瓧瀵归綈鐨勫叕寮忓�嶇畻锛坘b=sizeBytes/1024 浜岃繘鍒跺彛寰勶級 */
function sizeToMass(sizeBytes) {
